INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','present-continuous','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"present-continuous","title":"Present continuous","level":"A1","order":13,"summary":"Describe actions happening now with the right form of be and an -ing form.","learningGoals":["Actions in progress","Building the verb","Questions and negatives"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Actions in progress","explanation":"Use am, is or are plus an -ing form for an activity in progress now. The form of be agrees with the subject.","examples":["The dog is sleeping by the fire.","We are discussing the route."]},{"title":"Building the verb","explanation":"Many verbs add -ing. Usually remove a final silent e; some short verbs double their last consonant. Learn spelling with the verb.","examples":["write → writing","cut → cutting"]},{"title":"Questions and negatives","explanation":"Move be before the subject in a question. Put not after be in a negative. Keep the -ing form in both.","examples":["Are they loading the van?","I am not using the lift."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-continuous","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["The present continuous puts you inside an activity as it unfolds. Its two essential parts are a form of be and an -ing verb. It can describe the immediate moment or a temporary activity around now, such as a course this month. The form of be agrees with the subject; the -ing form does not."],"rules":[{"title":"Actions in progress","explanation":"Use am, is or are plus an -ing form for an activity in progress now. The form of be agrees with the subject.","examples":["The dog is sleeping by the fire.","We are discussing the route.","We **are renovating** the kitchen this month."],"pattern":"Subject + **am / is / are + -ing**","paragraphs":["I am studying this month need not mean that I am holding a book at the exact moment of speaking. The activity belongs to the current temporary period. Compare a stable habit, I study every evening, with an ongoing activity, I am studying now."],"id":"present-continuous-foundation-1","domain":"verbs","referenceIds":["bc-continuous","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Building the verb","explanation":"Many verbs add -ing. Usually remove a final silent e; some short verbs double their last consonant. Learn spelling with the verb.","examples":["write → writing","cut → cutting","She **isn’t using** the laptop right now."],"pattern":"make → mak**ing** · run → ru**nning** · lie → l**ying**","paragraphs":["A silent final e is usually dropped before -ing: make → making. Some short verbs double their final consonant: sit → sitting. Verbs ending in -ie change it to y: lie → lying. Spelling is partly lexical, so check unfamiliar verbs instead of adding letters blindly."],"id":"present-continuous-foundation-2","domain":"verbs","referenceIds":["bc-continuous","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Questions and negatives","explanation":"Move be before the subject in a question. Put not after be in a negative. Keep the -ing form in both.","examples":["Are they loading the van?","I am not using the lift.","**Are** you **waiting** for someone?"],"pattern":"**Are** they **working**? / They **are not working**.","paragraphs":["Only be moves in the question. The -ing form remains after the subject: Is she reading? In the negative, insert not after be: She is not reading. A short answer keeps only the auxiliary: Yes, she is."],"id":"present-continuous-foundation-3","domain":"verbs","referenceIds":["bc-continuous","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"State verbs such as know and own do not normally use continuous aspect in their ordinary senses. A verb can change sense: I think you are right expresses an opinion, while I am thinking about the problem describes an activity. The continuous can also describe a future arrangement.","examples":["We **are renovating** the kitchen this month.","She **isn’t using** the laptop right now.","**Are** you **waiting** for someone?"],"id":"present-continuous-foundation-4","domain":"verbs","referenceIds":["bc-continuous","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"domain":"verbs","id":"progressive-viewpoint","title":"Progressive aspect: activity, temporary situation and repeated irritation","explanation":"The progressive views a situation as unfolding around a reference point; it need not be happening at the exact instant of speaking. It can present a temporary arrangement or a repeated behaviour viewed emotionally, especially with always. Choosing simple or progressive changes viewpoint, not merely the length of an activity.","pattern":"She **works** here. / She **is working** here this month.","examples":["I’m **reading** a long novel at the moment.","You’re **always leaving** the lights on!"],"commonMistakes":["A short event can be progressive if it is viewed in progress, while a long-lasting state can be simple. Duration alone does not select the form."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"inflection","id":"spelling-endings","title":"Spelling changes with -s, -ed and -ing","explanation":"Common spelling patterns include consonant + y changing before -s or -ed, final silent e dropping before -ing, and a final consonant doubling after a short stressed vowel in suitable patterns. Vowel + y normally keeps y. These are spelling rules tied to sound and stress, with lexical and regional exceptions.","pattern":"stud**ies** · stud**ied** · study**ing**","examples":["**stop → stopped → stopping**","**make → making**, but **see → seeing**"],"commonMistakes":["Do not double w, x or y by the ordinary doubling rule. Travelling/traveling reflects a standard British/American spelling difference."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["Subject + **am / is / are + -ing**","make → mak**ing** · run → ru**nning** · lie → l**ying**","**Are** they **working**? / They **are not working**."],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["imperatives"],"readingReferenceIds":["bc-continuous","pcc-esol","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='present-continuous'
